 root.querySelectorAll('[data-study-report]').forEach(b=>b.onclick=()=>{const r=byId(b.dataset.studyReport);if(!r)return;const owner=tab==='visit'?'visit':'library',id=addStudyReport(r,owner);if(owner==='visit')visitView=id;else{libraryView=id;tab='library';}render();});
 root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{returnFocus={kind:'open',value:b.dataset.open};drawer=b.dataset.open;render();});
 root.querySelectorAll('[data-news-id]').forEach(b=>b.onclick=()=>openNews(b.dataset.newsId));
 root.onkeydown=ev=>{if(ev.key==='ArrowRight'||ev.key==='ArrowLeft'||ev.key==='Home'||ev.key==='End'){const tabs=[...root.querySelectorAll('[data-library-report],[data-visit-report]')];const at=tabs.indexOf(document.activeElement);if(at>=0){ev.preventDefault();const next=ev.key==='Home'?0:ev.key==='End'?tabs.length-1:(at+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;if(tab==='visit')visitView=tabs[next].dataset.visitReport;else libraryView=tabs[next].dataset.libraryReport;render();root.querySelector('#'+tabs[next].id)?.focus();return;}}if(ev.key==='Escape'&&drawer){ev.preventDefault();closeDrawer();}if(ev.key==='Tab'&&drawer){const nodes=root.querySelectorAll('.cv-drawer button:not([disabled]),.cv-drawer input,.cv-drawer select,.cv-drawer textarea,.cv-drawer a[href],.cv-drawer summary');const first=nodes[0],last=nodes[nodes.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}};
 const newsForm=root.querySelector('#cv-news-form');if(newsForm)newsForm.onsubmit=ev=>{ev.preventDefault();void act('news');};
 root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.tab!=='after')stopSpeech();tab=b.dataset.tab;message='';drawer='';llmKeyDraft='';render();});
 root.querySelectorAll('[data-prep-tab]').forEach(b=>{b.onclick=()=>{if(busy)return;preparationTab=b.dataset.prepTab;render();root.querySelector('#cv-prep-'+preparationTab)?.focus();};b.onkeydown=ev=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();ev.stopPropagation();if(busy)return;preparationTab=ev.key==='Home'?'fu':ev.key==='End'?'pre':preparationTab==='fu'?'pre':'fu';render();root.querySelector('#cv-prep-'+preparationTab)?.focus();}};});
 root.querySelectorAll('[data-fu-model]').forEach(n=>n.oninput=()=>{prepState()[n.dataset.fuModel]=n.value;persist();});
 root.querySelectorAll('[data-fu-row]').forEach(n=>n.oninput=()=>{const p=prepState();p.followupRows[Number(n.dataset.fuRow)]=n.value;p.prepQuestion=p.followupRows.filter(x=>x.trim()).join('\n');persist();});
 root.querySelectorAll('[data-fu-add]').forEach(b=>b.onclick=()=>{const p=prepState();if(p.followupRows.length>=20){message='질문은 최대 20줄까지 추가할 수 있습니다.';render();return;}const i=Number(b.dataset.fuAdd)+1;p.followupRows.splice(i,0,'');persist();render();root.querySelector('[data-fu-row="'+i+'"]')?.focus();});
 root.querySelectorAll('[data-fu-remove]').forEach(b=>b.onclick=()=>{const p=prepState();p.followupRows.splice(Number(b.dataset.fuRemove),1);p.prepQuestion=p.followupRows.filter(x=>x.trim()).join('\n');persist();render();});
 const fuSelect=root.querySelector('#cv-fu-visit');if(fuSelect)fuSelect.onchange=()=>{if(fuSelect.value==='')return;const v=m.visits[Number(fuSelect.value)],p=prepState();p.visitIndex=Number(fuSelect.value);p.previousQuestion=v.question;p.previousFollowup=v.followup;p.prepQuestion=v.question||v.followup||'';p.followupRows=[v.question,v.followup].filter(Boolean);if(!p.followupRows.length)p.followupRows=[''];p.prepQuestion=p.followupRows.join('\n');p.preparationResult=null;persist();render();};
 root.querySelectorAll('[data-model]').forEach(n=>n.oninput=()=>{m[n.dataset.model]=n.value;persist();});
 root.querySelectorAll('[data-check-review]').forEach(n=>n.oninput=()=>{m.reviewDraft[n.dataset.checkReview]=n.value;persist();});
 root.querySelectorAll('[data-draft]').forEach(n=>n.oninput=()=>{m.draft[n.dataset.draft]=n.value;persist();if(n.dataset.draft==='question')updateCaptureDOM();});
 const include=root.querySelector('#cv-include-transcript');if(include)include.onchange=()=>{m.includeTranscript=include.checked;persist();updateCaptureDOM();};
 root.querySelectorAll('[data-prep-remove]').forEach(b=>b.onclick=()=>{prepState().prepFiles.splice(Number(b.dataset.prepRemove),1);persist();render();});
 const upload=root.querySelector('#cv-prep-upload');if(upload)upload.onchange=async()=>{const files=[...upload.files];await work('prep-upload',async()=>{const p=prepState();p.prepFiles=p.prepFiles||[];for(const f of files){if(p.prepFiles.length>=3)throw Error('첨부는 최대 3개입니다.');if(f.size>5*1024*1024)throw Error('파일당 5MB까지 지원합니다.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f);});const result=await request('preparation/file',{name:f.name,base64});if(result.status!=='ok')throw Error(result.message);p.prepFiles.push({name:f.name,text:result.text});}});};
 const secret=root.querySelector('#cv-llm-key');if(secret)secret.oninput=()=>{llmKeyDraft=secret.value;};
 const modelInput=root.querySelector('#cv-llm-model');if(modelInput)modelInput.oninput=()=>{llmModelDraft=modelInput.value;};
 root.querySelectorAll('[data-hcp]').forEach(n=>n.oninput=()=>{const k=n.dataset.hcp;m.hcp[k]=n.value;if(['name','hospital'].includes(k)){m.hcp.id='custom';m.hcp.news=[];m.hcp.interests=[];m.hcp.relationship='새 프로필 · 공개 출처 확인 필요';m.hcp.affiliationDate='';m.hcpPapers=[];m.hcpMeta=null;}persist();});
 root.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{const s=searchExamples[Number(b.dataset.example)];m.query=s.query;m.trialQuery=s.trials;message='예시를 선택했습니다. 수정하거나 실제 검색을 눌러주세요.';render();});
 root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{libraryMode=b.dataset.mode;render();});
 root.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const id=b.dataset.pick,r=byId(id);if(!r)return;m.basket=m.basket.some(x=>canonical(x)===canonical(r))?m.basket.filter(x=>canonical(x)!==canonical(r)):[...m.basket,r];if(m.basket.some(x=>canonical(x)===canonical(r)))addStudyReport(r);persist();render();});
 root.querySelectorAll('[data-check]').forEach(n=>n.onchange=()=>{const i=Number(n.dataset.check);m.checks=n.checked?[...new Set([...m.checks,i])]:m.checks.filter(x=>x!==i);persist();});
 root.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{m.questionDraft=questionPrompts[Number(b.dataset.prompt)];persist();render();});
 root.querySelectorAll('[data-remove-question]').forEach(b=>b.onclick=()=>{m.questions.splice(Number(b.dataset.removeQuestion),1);persist();render();});
 root.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{reportMode=b.dataset.report;render();});
